const FOV = 66 * Math.PI / 180; // Field of view: 66 degrees
const moveSpeed = 3;            // moveSpeed: 3 cells/sec
const rotSpeed = 2;             // rotSpeed: 2 rad/sec
const playerRadius = 0.2;       // player radius: 0.2 cells
const minimapScale = 6;         // scale: 6px per cell
const DOOR_USE_DIST = 1.5;      // door opens within 1.5 cells + E
const TEX = 64;

