}
function makeBrick() {
  const c=document.createElement('canvas');c.width=c.height=TEX;
  const g=c.getContext('2d');
  g.fillStyle='#7d7d7d';g.fillRect(0,0,TEX,TEX); // mortar
  const bh=16,bw=32;
  for(let r=0;r<4;r++){
    const off=(r%2)*16;
    for(let bx=-1;bx<3;bx++){
      const x=bx*bw+off, y=r*bh;
      const v=((r*3+bx)%2===0)?0:12;
      g.fillStyle=`rgb(${150+v},${58+v*0.5},${40})`;
      g.fillRect(x+1,y+1,bw-2,bh-2);
      g.fillStyle='rgba(255,255,255,0.12)';g.fillRect(x+1,y+1,bw-2,2);
      g.fillStyle='rgba(0,0,0,0.25)';g.fillRect(x+1,y+bh-3,bw-2,2);
