}
function makeStripe() {
  const c=document.createElement('canvas');c.width=c.height=TEX;
  const g=c.getContext('2d');
  for(let x=0;x<TEX;x+=8){
    g.fillStyle='#2156ad';g.fillRect(x,0,8,TEX);
    g.fillStyle='#d6e2f5';g.fillRect(x+6,0,2,TEX);
  }
  g.fillStyle='rgba(0,0,0,0.18)';
  for(let y=0;y<TEX;y+=8) g.fillRect(0,y,TEX,1);
  return c;
}
function makeDoor() {
  const c=document.createElement('canvas');c.width=c.height=TEX;
  const g=c.getContext('2d');
  g.fillStyle='#6e451a';g.fillRect(0,0,TEX,TEX);
  for(let x=0;x<TEX;x+=16){ g.fillStyle='#4a2c0e';g.fillRect(x,0,2,TEX); }
  g.fillStyle='#7f5424';g.fillRect(6,6,52,22);g.fillRect(6,36,52,22);
  g.strokeStyle='#2c1a06';g.lineWidth=2;g.strokeRect(6,6,52,22);g.strokeRect(6,36,52,22);
  g.fillStyle='#1c1c1c';g.fillRect(0,0,TEX,3);g.fillRect(0,TEX-3,TEX,3);
  g.fillStyle='#ffdd55';g.fillRect(50,32,4,4);
  return c;
}
function initTextures(st){
  st.textures[1]=makeChecker();
  st.textures[2]=makeBrick();
  st.textures[3]=makeStripe();
  st.textures[4]=makeDoor();
}
function isSolid(st, wx, wy){
  const mx=Math.floor(wx), my=Math.floor(wy);
  if(my<0||my>=st.map.length||mx<0||mx>=st.map[0].length) return true;
  const cell=st.map[my][mx];
  if(cell===0||cell===5) return false;
  if(cell===4 && st.openDoors.has(mx+','+my)) return false; // opened door passable
  return true;
}

// ---------------- DDA RAYCASTING ----------------
// Digital Differential Analysis grid traversal.
// Returns perpendicular (fish-eye corrected) distance + texture coord.
function castRay(state, rayAngle){
  const px=state.player.x, py=state.player.y;
  const dirX=Math.cos(rayAngle), dirY=Math.sin(rayAngle);
  let mapX=Math.floor(px), mapY=Math.floor(py);
  const deltaX=Math.abs(1/(dirX===0?1e-30:dirX));
  const deltaY=Math.abs(1/(dirY===0?1e-30:dirY));
  let stepX,stepY,sideX,sideY;
  if(dirX<0){stepX=-1;sideX=(px-mapX)*deltaX;}else{stepX=1;sideX=(mapX+1-px)*deltaX;}
  if(dirY<0){stepY=-1;sideY=(py-mapY)*deltaY;}else{stepY=1;sideY=(mapY+1-py)*deltaY;}
  let side=0, wallType=0, hit=false, guard=0;
  let openDoorRaw=-1;
  while(!hit && guard++<256){
    if(sideX<sideY){sideX+=deltaX;mapX+=stepX;side=0;}
    else{sideY+=deltaY;mapY+=stepY;side=1;}
    if(mapX<0||mapY<0||mapY>=state.map.length||mapX>=state.map[0].length){wallType=1;hit=true;break;}
    const cell=state.map[mapY][mapX];
    if(cell===4 && state.openDoors.has(mapX+','+mapY)){
      if(openDoorRaw<0){
        const dRaw = (side===0)
          ? (mapX-px+(1-stepX)/2)/(dirX===0?1e-30:dirX)
          : (mapY-py+(1-stepY)/2)/(dirY===0?1e-30:dirY);
        openDoorRaw=dRaw;
      }
      continue; // see through open doorway
    }
    if(cell!==0 && cell!==5){ wallType=cell; hit=true; }
  }
  const rawDist = (side===0)
    ? (mapX-px+(1-stepX)/2)/(dirX===0?1e-30:dirX)
    : (mapY-py+(1-stepY)/2)/(dirY===0?1e-30:dirY);
  const safeRaw=Math.max(0.0001,rawDist);
  // Fish-eye correction: project Euclidean ray length onto view direction
  const correctedDist=Math.max(0.0001, safeRaw * Math.cos(rayAngle - state.player.angle));
  let doorCorrected=-1;
  if(openDoorRaw>0) doorCorrected=Math.max(0.0001, openDoorRaw * Math.cos(rayAngle - state.player.angle));
  // wall hit position for texture mapping
  let wallX = (side===0) ? py+safeRaw*dirY : px+safeRaw*dirX;
  wallX-=Math.floor(wallX);
  let texX=Math.floor(wallX*TEX);
  if(side===0 && dirX>0) texX=TEX-1-texX;
  if(side===1 && dirY<0) texX=TEX-1-texX;
  texX=Math.max(0,Math.min(TEX-1,texX));
  return {dist:correctedDist, rawDist:safeRaw, side, wallType, texX, mapX, mapY, doorDist:doorCorrected};
}

// ---------------- WALL COLUMN (perspective-correct textured) ----------------
function drawWallColumn(state, x, ray){
  const g=state.ctx;
  const lineHeight=H/ray.dist;
  const drawStart=H/2-lineHeight/2;
  const tex=state.textures[ray.wallType]||state.textures[1];
  // perspective-correct texture mapping: 1-px slice stretched by 1/dist
  g.drawImage(tex, ray.texX,0,1,TEX, x, drawStart,1,lineHeight);
  // Distance-based shading: multiply shade by 1/distance, clamped
  let shade = 1 / ray.dist;
  shade=Math.max(0.15,Math.min(1,shade));
  if(ray.side===1) shade*=0.7; // y-side darker for depth cue
  g.fillStyle=`rgba(0,0,0,${(1-shade).toFixed(3)})`;
  g.fillRect(x,drawStart,1,lineHeight);
  // Open archway lintel if ray passed through an open door before the wall
  if(ray.doorDist>0 && ray.doorDist < ray.dist){
    const dh=H/ray.doorDist;
    const top=H/2-dh/2;
    const lintelH=Math.max(2,dh*0.22);
    g.fillStyle='#6e451a';
    g.fillRect(x,top,1,lintelH);
    let ds=1/ray.doorDist; ds=Math.max(0.15,Math.min(1,ds));
    g.fillStyle=`rgba(0,0,0,${(1-ds).toFixed(3)})`;
    g.fillRect(x,top,1,lintelH);
    g.fillStyle='#2c1a06';g.fillRect(x,top+lintelH-1,1,1);
  }
}

// Exit portal sprite clipped by Z-buffer
function drawSprites(state){
  const g=state.ctx;
  const dx=state.exit.x-state.player.x, dy=state.exit.y-state.player.y;
  const spriteDist=Math.hypot(dx,dy);
  if(spriteDist<0.1) return;
  let ang=Math.atan2(dy,dx)-state.player.angle;
  while(ang>Math.PI)ang-=Math.PI*2; while(ang<-Math.PI)ang+=Math.PI*2;
  if(Math.abs(ang)>FOV/2+0.4) return;
  if(Math.cos(ang)<=0 && spriteDist>1) return;
  const perp=spriteDist*Math.cos(ang);
  const camX=Math.tan(ang)/Math.tan(FOV/2);
  const sx=(camX+1)/2*W;
  const size=H/Math.max(0.0001,perp);
  const w=size*0.7, x0=Math.floor(sx-w/2), x1=Math.floor(sx+w/2);
  const y0=H/2-size/2, y1=H/2+size/2;
  let shade=1/perp; shade=Math.max(0.2,Math.min(1,shade));
  for(let s=Math.max(0,x0);s<Math.min(W,x1);s++){
    // Z-buffer clip: avoid drawing behind walls
    if(perp < state.zBuffer[s]){
      const edge=Math.abs((s-sx)/(w/2)); // 0 center, 1 edge
      g.fillStyle = edge<0.35 ? '#7dffb0' : '#00cc55';
      g.fillRect(s,y0,1,y1-y0);
      g.fillStyle=`rgba(0,0,0,${((1-shade)*0.8+edge*0.2).toFixed(3)})`;
      g.fillRect(s,y0,1,y1-y0);
    }
  }
  // glow marker on top
  if(perp<state.zBuffer[Math.max(0,Math.min(W-1,Math.floor(sx)))]){
    g.fillStyle='#eaffea';g.fillRect(sx-2,H/2-2,4,4);
  }
}

// ---------------- MINIMAP ----------------
function drawMinimap(state){
  const g=state.ctx;
  const s=minimapScale; // 6px per cell
  g.save();
  g.fillStyle='rgba(0,0,0,0.65)';g.fillRect(6,6,state.map[0].length*s+4,state.map.length*s+4);
  for(let y=0;y<state.map.length;y++)for(let x=0;x<state.map[0].length;x++){
    const c=state.map[y][x];
    if(c===1)g.fillStyle='#8a8a8a';
    else if(c===2)g.fillStyle='#a05a3a';
    else if(c===3)g.fillStyle='#4a7dd6';
    else if(c===4)g.fillStyle=state.openDoors.has(x+','+y)?'#3a2a12':'#ff9a00';
    else if(c===5)g.fillStyle='#00ff66';
    else g.fillStyle='#101018';
    g.fillRect(8+x*s,8+y*s,s-0.5,s-0.5);
  }
  const px=8+state.player.x*s, py=8+state.player.y*s;
  g.fillStyle='#ffffff';g.beginPath();g.arc(px,py,3,0,Math.PI*2);g.fill();
  g.strokeStyle='#ff2222';g.lineWidth=2;g.beginPath();g.moveTo(px,py);
  g.lineTo(px+Math.cos(state.player.angle)*10,py+Math.sin(state.player.angle)*10);g.stroke();
  g.restore();
}

// ---------------- HUD ----------------
function nearestClosedDoor(state){
  let best=1e9,bx=-1,by=-1;
  for(let y=0;y<state.map.length;y++)for(let x=0;x<state.map[0].length;x++){
    if(state.map[y][x]===4 && !state.openDoors.has(x+','+y)){
      const d=Math.hypot(state.player.x-(x+0.5),state.player.y-(y+0.5));
      if(d<best){best=d;bx=x;by=y;}
    }
  }
  return {dist:best,x:bx,y:by};
}
function tryOpenDoor(state){
  if(state.finished) return;
  const n=nearestClosedDoor(state);
  if(n.dist<DOOR_USE_DIST && n.x>=0){ state.openDoors.add(n.x+','+n.y); }
}
function fmtTime(ms){
  const s=Math.floor(ms/1000), mm=String(Math.floor(s/60)).padStart(2,'0'), ss=String(s%60).padStart(2,'0');
  return mm+':'+ss;
}
function drawHUD(state, dt){
  const g=state.ctx;
  // FPS rolling average over last 30 frames, top-right
  state.frameTimes.push(dt); if(state.frameTimes.length>30) state.frameTimes.shift();
  const avg=state.frameTimes.reduce((a,b)=>a+b,0)/state.frameTimes.length;
  const fps=1/Math.max(1e-6,avg);
  g.fillStyle='rgba(0,0,0,0.55)';g.fillRect(W-110,8,102,22);
  g.fillStyle='#0f0';g.font='14px monospace';g.textAlign='right';
  g.fillText('FPS: '+fps.toFixed(0),W-14,24);
  g.textAlign='left';
  // crosshair
  g.fillStyle='#fff';g.fillRect(W/2-1,H/2-1,3,3);
  // Press E hint center-bottom when door within 1.5 cells
  const n=nearestClosedDoor(state);
  if(n.dist<1.5 && !state.finished){
    g.font='16px monospace';g.textAlign='center';
    const tw=g.measureText('Press E to open door').width;
    g.fillStyle='rgba(0,0,0,0.6)';g.fillRect(W/2-tw/2-8,H-44,tw+16,26);
    g.fillStyle='#ffe27a';g.fillText('Press E to open door',W/2,H-26);
    g.textAlign='left';
  }
  // LEVEL COMPLETE overlay
  if(state.finished){
    g.fillStyle='rgba(0,0,0,0.65)';g.fillRect(0,0,W,H);
    g.fillStyle='#00ff88';g.font='bold 34px monospace';g.textAlign='center';
    g.fillText('LEVEL COMPLETE — '+fmtTime(state.finishElapsed),W/2,H/2);
    g.font='16px monospace';g.fillStyle='#fff';
    g.fillText('Press R to restart',W/2,H/2+34);
    g.textAlign='left';
    const el=document.getElementById('win');
    el.style.display='block';el.textContent='LEVEL COMPLETE — '+fmtTime(state.finishElapsed);
  }
}

// ---------------- INPUT + COLLISION ----------------
function handleInput(state, dt){
  // keyboard rotation (ArrowLeft/Right) using rotSpeed
  if(state.keys['ArrowLeft']) state.player.angle-=rotSpeed*dt;
  if(state.keys['ArrowRight']) state.player.angle+=rotSpeed*dt;
  const cos=Math.cos(state.player.angle), sin=Math.sin(state.player.angle);
  let fwd=0,str=0;
  if(state.keys['KeyW']||state.keys['ArrowUp']) fwd+=1;
  if(state.keys['KeyS']||state.keys['ArrowDown']) fwd-=1;
  if(state.keys['KeyD']) str+=1;   // strafe right
  if(state.keys['KeyA']) str-=1;   // strafe left
  const step=moveSpeed*dt;
  const dx=(cos*fwd + -sin*str)*step;
  const dy=(sin*fwd + cos*str)*step;
  const r=playerRadius; // AABB radius 0.2 cells
  // AABB collision: test X and Y separately against all solid walls
  function collides(nx,ny){
    return isSolid(state,nx-r,ny-r)||isSolid(state,nx+r,ny-r)||
           isSolid(state,nx-r,ny+r)||isSolid(state,nx+r,ny+r);
  }
  const nx=state.player.x+dx;
  if(!collides(nx,state.player.y)) state.player.x=nx;
  const ny=state.player.y+dy;
  if(!collides(state.player.x,ny)) state.player.y=ny;
}

// ---------------- MAIN LOOP ----------------
let lastT=0;
function gameLoop(now){
  requestAnimationFrame(gameLoop);
  if(!lastT) lastT=now;
  let dt=(now-lastT)/1000; lastT=now;
  if(dt>0.05) dt=0.05; if(dt<=0) dt=0.0001;
  if(!state.finished) handleInput(state, dt);
  else if(state.keys['KeyR']){
    state.player.x=state.spawn.x;state.player.y=state.spawn.y;state.player.angle=state.spawn.angle;
    state.finished=false;state.openDoors.clear();state.startTime=performance.now();
    document.getElementById('win').style.display='none';
  }
  // Ceiling flat dark, floor slightly lighter flat
  state.ctx.fillStyle='#0b0b18';state.ctx.fillRect(0,0,W,H/2);
  state.ctx.fillStyle='#2b2b3d';state.ctx.fillRect(0,H/2,W,H/2);
  const tanHalf=Math.tan(FOV/2);
  for(let x=0;x<W;x++){
    const cameraX=2*x/W-1;
    const rayAngle=state.player.angle+Math.atan(cameraX*tanHalf);
    const ray=castRay(state, rayAngle);
    state.zBuffer[x]=ray.dist; // maintain per-column Z-buffer
    drawWallColumn(state, x, ray);
  }
  drawSprites(state);   // uses state.zBuffer to clip behind walls
  drawMinimap(state);
  drawHUD(state, dt);
  // exit check
  if(!state.finished){
    const cx=Math.floor(state.player.x), cy=Math.floor(state.player.y);
    if(state.map[cy] && state.map[cy][cx]===5){
      state.finished=true;state.finishElapsed=performance.now()-state.startTime;
    }
  }
}

// ---------------- BOOT + EVENTS ----------------
state.map=initMap();
initTextures(state);
window.addEventListener('keydown',e=>{
  state.keys[e.code]=true;
  if(e.code==='KeyE') tryOpenDoor(state);
  if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code)) e.preventDefault();
});
window.addEventListener('keyup',e=>{state.keys[e.code]=false;});
canvas.addEventListener('click',()=>{ if(canvas.requestPointerLock) canvas.requestPointerLock(); });
document.addEventListener('mousemove',e=>{
  if(document.pointerLockElement===canvas) state.player.angle+=e.movementX*0.0025; // Mouse-look horizontal
});
requestAnimationFrame(gameLoop);
</script>
